import {Align, arrayAlign} from "@kvisaz/phaser-sugar";
import {getLocalizedText, ViewElementBuilder} from "../../../../assets";
import {StateConnector} from "../../../../common";
import {ExternalTopbarDialog} from "../../../../common/game-core";
import {ISettingsState} from "../../../../logic";

interface ISettingsDialogProps {
    scene: Phaser.Scene;
    settings: StateConnector<ISettingsState>;
    onCloseClick?: () => void;
}

const dialogWidth = 1100;
const dialogHeight = 560;
const contentWidth = 420;
const contentHeight = 390;

export class SettingsDialog {
    constructor(private readonly props: ISettingsDialogProps) {
    }

    create(): ExternalTopbarDialog {
        const title = getLocalizedText("settings.title");
        const builder = new ViewElementBuilder(this.props.scene);
        const contentBg = builder.nineSliceDialogGroup(contentWidth, contentHeight);
        const soundSwitch = builder.buttonSwitchSound((isOn) => {
            this.props.settings.setState((prev) => ({
                ...prev,
                isSoundOn: isOn,
                isMusicOn: isOn ? prev.isMusicOn : false,
            }));
        });
        const musicSwitch = builder.buttonSwitchMusic((isOn) => {
            this.props.settings.setState((prev) => ({
                ...prev,
                isMusicOn: isOn,
            }));
        });

        const align = new Align();
        const {alignObject, column} = arrayAlign;

        align.anchor(contentBg).center(alignObject(column([soundSwitch, musicSwitch])));

        const dialogContent = this.props.scene.add.container(0, 0, [contentBg, soundSwitch, musicSwitch]);
        const applyStateToControls = (state: ISettingsState) => {
            soundSwitch.switch(state.isSoundOn);
            const effectiveMusic = state.isSoundOn ? state.isMusicOn : false;
            musicSwitch.switch(effectiveMusic);
            musicSwitch.enable(state.isSoundOn);
        };

        applyStateToControls(this.props.settings.getState());
        const unSubState = this.props.settings.on(applyStateToControls);

        const dialog = builder.dialogExternalTopTitle({
            beforeOpen: () => applyStateToControls(this.props.settings.getState()),
            content: dialogContent,
            title,
            width: dialogWidth,
            height: dialogHeight,
            onCloseClick: this.props.onCloseClick,
        });

        dialog.once(Phaser.GameObjects.Events.DESTROY, unSubState);

        return dialog;
    }
}
