import {PreloadTask} from "@kvisaz/phaser-sugar";
import {addHtmlLoaderToPhaser, getUrlParam} from "../../common";
import {Scenes} from "../../common/game-core";
import {ViewElementBuilder} from "../../assets";
import {GameServiceProvider} from "../../services";
import { preloadGamePlayCardAssets } from "../shared";

export class BootScene extends Phaser.Scene {
    constructor() {
        super(Scenes.Boot);
    }

    preload() {
        const scene = this;

        addHtmlLoaderToPhaser({
            scene: this,
            loaderVarHosId: "loader",
            cssVarProgressName: "--progress",
        });

        new ViewElementBuilder(this).preload();
        preloadGamePlayCardAssets(this);
        PreloadTask.load(this, GameServiceProvider.get().preload());
    }

    create() {
        /** запуск тестовой сцены - не забудь добавить ее в индексный список scenes/index **/
        const testScene = getUrlParam("testScene");
        if (testScene) {
            this.scene.launch(testScene);
            return;
        }

        /** обычный запуск игры, клондайк для сравнения что ничего не сломалось в общих файлах **/
        const isKlondikeEnabled = getUrlParam("klondike") != null;
        this.scene.launch(isKlondikeEnabled ? Scenes.Game : Scenes.SpiderStart);
    }
}
