import {ViewElementBuilder} from "../../../../assets";
import {SceneEvents} from "../../../../common";
import {ExternalTopbarDialog} from "../../../../common/game-core";
import {OverlayScene} from "../../../../common/scenes";
import {
    ILogicShopItem,
    isInAppPurchaseId,
    PurchaseId,
    isRewardPurchaseId,
} from "../../../../logic";
import {GameServiceProvider} from "../../../../services";
import {OneButtonDialog} from "../../dialog";
import {IGameShopEvents} from "./events";

interface IGameShopProps {
    scene: Phaser.Scene;
}

/**
 * Читает уже подготовленные сервисом товары и оставляет reward-позиции
 * только когда реклама доступна.
 */
const getGameShopItems = (): ILogicShopItem[] => {
    const gameService = GameServiceProvider.get();
    const shopItems = Object.values(gameService.getShopItems() ?? {});
    const isRewardEnabled = gameService.isRewardAdEnabled;
    return shopItems.filter((item) => (item.rewardAdPrice ? isRewardEnabled : true));
};

export function getGameShop(props: IGameShopProps): GameShop | undefined {
    const gameService = GameServiceProvider.get();
    if (!gameService.isShopEnabled) {
        return;
    }

    if (getGameShopItems().length === 0) {
        return;
    }

    return new GameShop(props);
}

export class GameShop extends Phaser.GameObjects.Container {
    private dialog?: ExternalTopbarDialog;
    private readonly sceneEvents: SceneEvents<IGameShopEvents>;
    private readonly oneButtonDialog: OneButtonDialog;

    constructor(private readonly props: IGameShopProps) {
        super(props.scene);
        this.sceneEvents = new SceneEvents({scene: props.scene, autoUnSub: this});
        this.oneButtonDialog = new OneButtonDialog({scene: props.scene});

        const builder = new ViewElementBuilder(props.scene);
        const button = builder.buttonShop(() => this.showDialog());

        this.add(button);
        props.scene.add.existing(this);
    }

    destroy(fromScene?: boolean): void {
        this.dialog?.destroy();
        this.dialog = undefined;
        this.oneButtonDialog.destroy();
        super.destroy(fromScene);
    }

    private showDialog(): void {
        const overlayScene = OverlayScene.get(this.props.scene);
        const shopItems = getGameShopItems();
        if (shopItems.length === 0) {
            this.setVisible(false);
            return;
        }

        this.setVisible(true);

        this.dialog?.destroy();

        const builder = new ViewElementBuilder(overlayScene);
        this.dialog = builder.dialogShop({
            shopItems,
            onClose: () => {
                this.dialog = undefined;
            },
            onItemBuyClick: (item) => this.onItemBuyClick(item),
        });
        this.dialog.show();
    }

    private onItemBuyClick(item: ILogicShopItem): void {
        if (!isInAppPurchaseId(item.id) && !isRewardPurchaseId(item.id)) {
            console.warn("unknown game purchase id", item.id);
            return;
        }

        void this.purchaseItem(item.id);
    }

    private async purchaseItem(id: PurchaseId): Promise<void> {
        /**
         * Покупка всегда идет через GameService/ShopService.
         * Здесь только UI-реакция:
         * - ошибка => диалог с предупреждением;
         * - успех => диалог спасибо + событие для остального UI сцены.
         */
        const result = await GameServiceProvider.get().shopPurchase(id);
        if ("error" in result) {
            console.warn("game shop purchase failed", result.error);
            this.showErrorDialog();
            return;
        }

        this.showSuccessDialog();
        this.sceneEvents.emit("gameShopPurchaseApplied", {purchaseId: id});
    }

    private showSuccessDialog(): void {
        /** Закрываем текущий shop-диалог и показываем простой one-button фидбек. */
        this.dialog?.close();
        this.oneButtonDialog.show({
            text: "Спасибо за покупку",
            buttonText: "Ok",
        });
    }

    private showErrorDialog(): void {
        /** Ошибка покупки обрабатывается user-facing сообщением без падения сцены. */
        this.dialog?.close();
        this.oneButtonDialog.show({
            text: "Ой, ошибка. Повторите попозже",
            buttonText: "Ok",
        });
    }
}
