import {ILayoutConfig, layoutConfig} from './config';
import {Align, AlignObject} from '@kvisaz/phaser-sugar';
import {ScenePlaceType} from './types';
import {sideBar, sideBarVertical} from './sidebar';

interface IProps {
    scene: Phaser.Scene;
}

export class SceneLayout {
    private config: ILayoutConfig = layoutConfig;
    private align = new Align();

    constructor(private props: IProps) {
    }

    sidebar({
        children,
        place,
        direction = 'horizontal',
    }: {
        children: AlignObject[];
        place: ScenePlaceType;
        direction?: 'vertical' | 'horizontal';
    }) {
        const {screenPadding, sideBarHorizontalGap, sideBarVerticalGap} = this.config;
        const gap = direction === 'vertical' ? sideBarVerticalGap : sideBarHorizontalGap;
        console.log(`
        direction ${direction}
            gap ${gap}
            screenPadding ${screenPadding}
        `)
        const sideBarAlignObject =
            direction === 'vertical'
                ? sideBarVertical({children, gap})
                : sideBar({children, gap});

        const sceneAlign = this.align.anchorSceneScreen(this.props.scene);

        switch (place) {
            case ScenePlaceType.TOP_LEFT:
                sceneAlign.topIn(sideBarAlignObject, screenPadding).leftIn(sideBarAlignObject, screenPadding);
                break;
            case ScenePlaceType.TOP_CENTER:
                sceneAlign.topIn(sideBarAlignObject, screenPadding).centerX(sideBarAlignObject);
                break;
            case ScenePlaceType.TOP_RIGHT:
                sceneAlign.topIn(sideBarAlignObject, screenPadding).rightIn(sideBarAlignObject, -screenPadding);
                break;
            case ScenePlaceType.CENTER_LEFT:
                sceneAlign.centerY(sideBarAlignObject).leftIn(sideBarAlignObject, screenPadding);
                break;
            case ScenePlaceType.CENTER_CENTER:
                sceneAlign.center(sideBarAlignObject);
                break;
            case ScenePlaceType.CENTER_RIGHT:
                sceneAlign.centerY(sideBarAlignObject).rightIn(sideBarAlignObject, -screenPadding);
                break;
            case ScenePlaceType.BOTTOM_LEFT:
                sceneAlign.bottomIn(sideBarAlignObject, -screenPadding).leftIn(sideBarAlignObject, screenPadding);
                break;
            case ScenePlaceType.BOTTOM_CENTER:
                sceneAlign.bottomIn(sideBarAlignObject, -screenPadding).centerX(sideBarAlignObject);
                break;
            case ScenePlaceType.BOTTOM_RIGHT:
                sceneAlign.bottomIn(sideBarAlignObject, -screenPadding).rightIn(sideBarAlignObject, -screenPadding);
                break;
        }

        return sideBarAlignObject;
    }
}
