import { Align } from "@kvisaz/phaser-sugar";
import { ViewElementBuilder } from "../../../../../assets";
import { cardBacksChibiPack01AutoAssetsConst } from "../../../../../assets/figmaAssets/card-backs-chibi-pack-01-assets";
import { SceneEvents } from "../../../../../common";
import { ISpiderGameUiEvents } from "../../events";

interface IProps {
  scene: Phaser.Scene;
}

const BACK_ASSET_KEYS = Object.keys(cardBacksChibiPack01AutoAssetsConst);
const FONT_SIZE_PX = 20;
const VALUE_TEXT_FONT_SIZE = "24px";
const VALUE_TEXT_COLOR = "#ffffff";
const VALUE_TEXT_OFFSET = 6;

export function getSpiderCardBackButton(props: IProps): Phaser.GameObjects.Container {
  const align = new Align();
  const sceneEvents = new SceneEvents<ISpiderGameUiEvents>({ scene: props.scene });
  const builder = new ViewElementBuilder(props.scene);

  let nextBackThemeIndex = 1;
  let currentBackTheme = BACK_ASSET_KEYS[0];

  const valueText = builder.textMain(currentBackTheme, {
    color: VALUE_TEXT_COLOR,
    fontSize: VALUE_TEXT_FONT_SIZE,
  });

  const button = builder.buttonSecondary("Рубашка", () => {
    const nextBackTheme = BACK_ASSET_KEYS[nextBackThemeIndex];
    sceneEvents.emit("cardThemeBackChange", { backAssetKey: nextBackTheme });

    currentBackTheme = nextBackTheme;
    valueText.setText(currentBackTheme);
    nextBackThemeIndex = (nextBackThemeIndex + 1) % BACK_ASSET_KEYS.length;
  }, {
    fontSizePx: FONT_SIZE_PX,
    paddingY: 5,
  });

  const container = props.scene.add.container(0, 0, [button, valueText]);
  align.anchor(button).bottomTo(valueText, VALUE_TEXT_OFFSET).centerX(valueText);

  return container;
}
